#!/usr/bin/env python3
"""AngKer SMM Panel launcher for Python-only hosts.

Does everything automatically on a machine that has only Python:
  1. downloads a portable Node.js (no root needed) into ./.runtime if node/npm is missing
  2. downloads cloudflared into ./bin if missing (used by tunnel.sh)
  3. npm install  (first run)  ->  npm run build  (first run / after code changes)
  4. starts the web app on 127.0.0.1:15794 + the Cloudflare tunnel
  5. calls /api/internal/worker every minute (orders, status sync, deposits)
"""
import base64, hashlib, io, os, platform, re, secrets, shutil, socket, signal, subprocess, sys, tarfile, threading, time, urllib.request, urllib.parse, zipfile
from pathlib import Path

EMBED_B64 = ""
FORCE_ENV_KEYS = ("ADMIN_USERNAME", "ADMIN_EMAIL", "ADMIN_PASSWORD")   # always taken from the project's .env (the owner login)
ROOT = Path(__file__).resolve().parent
HOST = "127.0.0.1"
PORT = int(os.environ.get("APP_PORT", "15794"))   # must match the tunnel's service URL (http://localhost:15794)
NODE_VERSION = "v20.18.1"
RUNTIME = ROOT / ".runtime"
TUNNEL_SH = ROOT / "tunnel.sh"

def locate():
    return next((p for p in (ROOT / "angker-ready", ROOT.parent / "angker-ready", ROOT) if (p / "package.json").exists()), None)


APP_DIR = locate()


def log(*a):
    print("[main]", *a, flush=True)


def arch():
    m = platform.machine().lower()
    return {"x86_64": "x64", "amd64": "x64", "aarch64": "arm64", "arm64": "arm64", "armv7l": "armv7l"}.get(m) or sys.exit(f"[main] unsupported CPU: {m}")


def download(url, dest):
    log("downloading", url)
    req = urllib.request.Request(url, headers={"User-Agent": "angker-launcher"})
    with urllib.request.urlopen(req, timeout=120) as r, open(dest, "wb") as f:
        shutil.copyfileobj(r, f)


def ensure_node():
    """Returns an env PATH-prefix dir containing node/npm."""
    if shutil.which("node") and shutil.which("npm"):
        try:
            v = subprocess.check_output(["node", "-v"], text=True).strip().lstrip("v")
            if tuple(int(x) for x in v.split(".")[:2]) >= (18, 18):
                return None
        except Exception:
            pass
    musl = Path("/etc/alpine-release").exists()
    name = f"node-{NODE_VERSION}-linux-{arch()}" + ("-musl" if musl else "")
    bindir = RUNTIME / name / "bin"
    if not (bindir / "node").exists():
        RUNTIME.mkdir(exist_ok=True)
        base = "https://unofficial-builds.nodejs.org/download/release" if musl else "https://nodejs.org/dist"
        tgz = RUNTIME / f"{name}.tar.gz"
        download(f"{base}/{NODE_VERSION}/{name}.tar.gz", tgz)
        with tarfile.open(tgz) as t:
            try:
                t.extractall(RUNTIME, filter="data")
            except TypeError:                       # Python < 3.12 has no filter argument
                t.extractall(RUNTIME)
        tgz.unlink(missing_ok=True)
    return str(bindir)


def ensure_cloudflared():
    if shutil.which("cloudflared") or (ROOT / "bin" / "cloudflared").exists():
        return
    a = {"x64": "amd64", "arm64": "arm64", "armv7l": "arm"}[arch()]
    (ROOT / "bin").mkdir(exist_ok=True)
    dest = ROOT / "bin" / "cloudflared"
    download(f"https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-{a}", dest)
    dest.chmod(0o755)


def sync_from_zip():
    """Unpack the project into ./angker-ready.
    Source 1: the project embedded inside this very file (single-file deploy: upload only main.py).
    Source 2: the newest *.zip next to main.py that contains angker-ready/ (it may also carry a newer main.py).
    Re-done only when the source changed or a required file is missing. An existing .env keeps its values
    (missing variables are appended); node_modules and tunnel.sh are never touched."""
    target = ROOT / "angker-ready"
    embedded = bool(EMBED_B64)
    if embedded:
        data = base64.b64decode(EMBED_B64)
        opener = lambda: zipfile.ZipFile(io.BytesIO(data))
        sig = "embedded:" + hashlib.sha256(data).hexdigest()[:20]
        label = "the project embedded in main.py"
    else:
        zips = []
        for z in ROOT.glob("*.zip"):
            try:
                with zipfile.ZipFile(z) as zf:
                    if "angker-ready/package.json" in zf.namelist():
                        zips.append(z)
            except Exception:
                pass
        if not zips:
            return
        z = max(zips, key=lambda p: p.stat().st_mtime)
        opener = lambda: zipfile.ZipFile(z)
        sig = f"{z.name}:{z.stat().st_size}:{int(z.stat().st_mtime)}"
        label = z.name
    marker = target / ".zip-applied"
    required = [target / r for r in ("package.json", "postcss.config.js", "prisma/schema.prisma", "scripts/predeploy.mjs", "src/app/layout.tsx")]
    if marker.exists() and marker.read_text() == sig and all(p.exists() for p in required):
        return
    log("unpacking", label, "->", target)
    base = target.resolve()
    n = 0
    with opener() as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            if info.filename == "tunnel.sh" and not TUNNEL_SH.exists():
                TUNNEL_SH.write_bytes(zf.read(info))
                continue
            if not info.filename.startswith("angker-ready/"):
                continue
            rel = info.filename[len("angker-ready/"):]
            dest = (target / rel).resolve()
            if base not in dest.parents:                       # zip-slip guard
                continue
            if rel == ".env" and dest.exists():                 # keep the user's values, only add variables that are missing
                have = read_env_file(dest)
                lines = [l for l in zf.read(info).decode("utf-8", "replace").splitlines() if "=" in l and not l.strip().startswith("#")]
                forced = {l.split("=", 1)[0].strip(): l.split("=", 1)[1].strip() for l in lines if l.split("=", 1)[0].strip() in FORCE_ENV_KEYS}
                if any(have.get(k) != v for k, v in forced.items()):
                    kept = [l for l in dest.read_text(encoding="utf-8").splitlines() if l.split("=", 1)[0].strip() not in forced]
                    dest.write_text("\n".join(kept) + "\n" + "\n".join(f"{k}={v}" for k, v in forced.items()) + "\n", encoding="utf-8")
                    log("updated .env:", ", ".join(forced))
                    have = read_env_file(dest)
                add = [l for l in lines if l.split("=", 1)[0].strip() not in have]
                if add:
                    with open(dest, "a", encoding="utf-8") as out:
                        out.write("\n" + "\n".join(add) + "\n")
                    log("added missing .env variables:", ", ".join(l.split("=", 1)[0].strip() for l in add))
                continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(info) as src, open(dest, "wb") as out:
                shutil.copyfileobj(src, out)
            n += 1
    marker.write_text(sig)
    log(f"unpacked {n} files")
    if not embedded:
        try:                                                      # a newer main.py inside the zip replaces this one, then restarts itself
            with opener() as zf:
                new_main = zf.read("main.py")
            me = Path(__file__).resolve()
            if new_main != me.read_bytes():
                me.write_bytes(new_main)
                log("main.py updated from the zip, restarting")
                os.execv(sys.executable, [sys.executable, str(me)])
        except KeyError:
            pass


def isolate_db(env, env_file):
    """Keep AngKer's tables in their own PostgreSQL schema (default "angker") on the DIRECT (non-pooler) connection.
    A shared database that already holds other tables (e.g. `users`) makes `prisma db push` refuse to run, which
    left the site without its newest tables/columns (admin, API key, payment settings). Set DB_SCHEMA=public to disable."""
    schema = (os.environ.get("DB_SCHEMA") or env_file.get("DB_SCHEMA") or "angker").strip()
    if schema.lower() == "public":
        return
    base = env.get("DIRECT_URL") or env_file.get("DIRECT_URL") or env.get("DATABASE_URL") or env_file.get("DATABASE_URL")
    if not base:
        return
    u = urllib.parse.urlsplit(base)
    host = re.sub(r"-pooler(?=[.:/]|$)", "", u.netloc)                     # Neon: pooled host -> direct host
    q = urllib.parse.parse_qsl(u.query, keep_blank_values=True)
    if not any(k == "schema" for k, _ in q):
        q.append(("schema", schema))
    q = [(k, v) for k, v in q if k != "pgbouncer"]
    url = urllib.parse.urlunsplit((u.scheme, host, u.path, urllib.parse.urlencode(q), u.fragment))
    env["DATABASE_URL"] = env["DIRECT_URL"] = url
    log(f"database: using schema '{dict(q)['schema']}' on host {urllib.parse.urlsplit(url).hostname}")


def read_env_file(path):
    out = {}
    if path.exists():
        for line in path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                out[k.strip()] = v.strip().strip('"').strip("'")
    return out


def run(cmd, env, cwd):
    log("$", " ".join(cmd))
    if subprocess.call(cmd, cwd=cwd, env=env) != 0:
        sys.exit(f"[main] ERROR: command failed: {' '.join(cmd)}")


def newest_source_mtime():
    latest = 0
    for sub in ("src", "prisma", "public"):
        for p in (APP_DIR / sub).rglob("*"):
            if p.is_file():
                latest = max(latest, p.stat().st_mtime)
    for f in ("package.json", "next.config.mjs", "tailwind.config.ts"):
        if (APP_DIR / f).exists():
            latest = max(latest, (APP_DIR / f).stat().st_mtime)
    return latest


def prepare(env):
    npm = ["npm"]
    if not (APP_DIR / "node_modules" / "next").exists():
        run(npm + ["install", "--no-audit", "--no-fund"], env, APP_DIR)          # also runs prisma generate
    build_id = APP_DIR / ".next" / "BUILD_ID"
    if not build_id.exists() or newest_source_mtime() > build_id.stat().st_mtime:
        shutil.rmtree(APP_DIR / ".next" / "cache", ignore_errors=True)            # a failed build must not leave a poisoned cache behind
        run(npm + ["run", "build"], env, APP_DIR)                                  # predeploy.mjs: prisma db push + seed, then next build


def ensure_embedded_db_scaffold(d: Path):
    """Write minimal package.json + server.mjs for embedded-postgres if the folder is empty/missing."""
    d.mkdir(parents=True, exist_ok=True)
    pkg = d / "package.json"
    srv = d / "server.mjs"
    if not pkg.exists():
        pkg.write_text(
            '{"name":"angker-embedded-db","private":true,"dependencies":{"embedded-postgres":"15.18.0-beta.17"}}\n',
            encoding="utf-8",
        )
        log("wrote", pkg)
    if not srv.exists():
        srv.write_text(
            """import EmbeddedPostgres from 'embedded-postgres';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const port = Number(process.env.PG_PORT || 5433);
const password = process.env.PG_PASSWORD || 'angker';
const dataDir = join(process.cwd(), '..', 'pgdata');
mkdirSync(dataDir, { recursive: true });
const pg = new EmbeddedPostgres({ databaseDir: dataDir, user: 'angker', password, port, persistent: true });
await pg.initialise();
await pg.start();
await pg.createDatabase('angker').catch(() => {});
console.log('[embedded-db] postgres ready on', port);
process.on('SIGTERM', async () => { try { await pg.stop(); } catch {} process.exit(0); });
process.on('SIGINT', async () => { try { await pg.stop(); } catch {} process.exit(0); });
""",
            encoding="utf-8",
        )
        log("wrote", srv)


def start_embedded_db(env):
    """No DATABASE_URL given -> run a local PostgreSQL (data kept in ./pgdata). Returns (process, url) or (None, None)."""
    pgport = int(os.environ.get("PG_PORT", "5433"))
    pwf = RUNTIME / "pg_password"
    RUNTIME.mkdir(exist_ok=True)
    if not pwf.exists():
        pwf.write_text(secrets.token_hex(16))
        pwf.chmod(0o600)
    pw = pwf.read_text().strip()
    d = ROOT / "embedded-db"
    try:
        ensure_embedded_db_scaffold(d)
        if not (d / "node_modules" / "embedded-postgres").exists():
            run(["npm", "install", "--no-audit", "--no-fund"], env, d)
        proc = subprocess.Popen(["node", "server.mjs"], cwd=d, env={**env, "PG_PASSWORD": pw, "PG_PORT": str(pgport)})
        for _ in range(120):
            if proc.poll() is not None:
                raise RuntimeError("embedded postgres exited (see log above)")
            try:
                socket.create_connection(("127.0.0.1", pgport), timeout=1).close()
                time.sleep(2)
                return proc, f"postgresql://angker:{pw}@127.0.0.1:{pgport}/angker"
            except OSError:
                time.sleep(1)
        raise RuntimeError("timeout waiting for embedded postgres")
    except (SystemExit, Exception) as e:
        log("!! embedded database failed:", e)
        return None, None


def db_setup(env, env_file):
    """Every start: create/update tables + seed (idempotent), so changing DATABASE_URL never needs a rebuild."""
    url = env.get("DIRECT_URL") or env.get("DATABASE_URL") or env_file.get("DIRECT_URL") or env_file.get("DATABASE_URL")
    if not url:
        log("!! DATABASE_URL is empty -> register/login/bot cannot work. Set it in angker-ready/.env, then restart.")
        return False
    e = {**env, "DATABASE_URL": url}
    ok = subprocess.call(["npx", "prisma", "db", "push", "--skip-generate"], cwd=APP_DIR, env=e, stdin=subprocess.DEVNULL) == 0
    if ok:
        seeded = subprocess.call(["npx", "prisma", "db", "seed"], cwd=APP_DIR, env=e, stdin=subprocess.DEVNULL) == 0
        log("database ready" + ("" if seeded else " (but the seed step failed: admin login / settings may be missing, see the log above)"))
    else:
        log("!! prisma db push failed: check DATABASE_URL (must be a reachable PostgreSQL URL)")
    return ok


def worker_loop(env_file, stop_evt):
    """Replaces Vercel Cron: runs outbox / order sync / deposit reconcile every minute."""
    secret = os.environ.get("CRON_SECRET") or env_file.get("CRON_SECRET", "")
    if not secret:
        log("CRON_SECRET missing: worker loop disabled (orders will not be sent to the provider!)")
        return
    url = f"http://{HOST}:{PORT}/api/internal/worker"
    while not stop_evt.wait(60):
        try:
            req = urllib.request.Request(url, headers={"Authorization": f"Bearer {secret}"})
            urllib.request.urlopen(req, timeout=60).read()
        except Exception as e:
            log("worker call failed:", str(e)[:120])


def ensure_tunnel_sh():
    """Create a no-op tunnel.sh if missing so Apsara / hosts without Cloudflare still start."""
    if TUNNEL_SH.exists():
        return
    # Exit code 2 = "disabled" (main loop keeps the app running without restarting tunnel)
    TUNNEL_SH.write_text(
        "#!/usr/bin/env bash\n"
        "# Auto-created: no Cloudflare tunnel token on this host.\n"
        "# Panel already exposes the app publicly — tunnel is optional.\n"
        "# To enable: put your cloudflared token below and restart.\n"
        "echo \"[tunnel] disabled (no token). App still runs on localhost.\"\n"
        "exit 2\n",
        encoding="utf-8",
    )
    try:
        TUNNEL_SH.chmod(0o755)
    except Exception:
        pass
    log("created", TUNNEL_SH, "(disabled placeholder)")


def start_tunnel():
    ensure_tunnel_sh()
    try:
        TUNNEL_SH.chmod(0o755)
    except Exception as e:
        log("!! tunnel.sh chmod failed:", e)
    if not TUNNEL_SH.exists():
        log("!! tunnel.sh missing — running without tunnel")
        return subprocess.Popen(["sleep", "infinity"])
    return subprocess.Popen(["bash", str(TUNNEL_SH)], cwd=ROOT)


def main():
    global APP_DIR
    sync_from_zip()
    APP_DIR = locate()
    if APP_DIR is None:
        sys.exit("[main] ERROR: រកមិនឃើញថត angker-ready (package.json) ក្បែរ main.py ទេ។")
    env_file = read_env_file(APP_DIR / ".env")
    env = {**os.environ, "PORT": str(PORT), "HOSTNAME": HOST, "NEXT_TELEMETRY_DISABLED": "1"}
    env.setdefault("NODE_OPTIONS", "--max-old-space-size=1536")                    # keep `next build` from eating all RAM
    node_bin = ensure_node()
    if node_bin:
        env["PATH"] = node_bin + os.pathsep + env.get("PATH", "")
    ensure_cloudflared()
    for k in ("DATABASE_URL", "APP_URL"):
        if not (env.get(k) or env_file.get(k)):
            log(f"WARNING: {k} is empty (set it in angker-ready/.env or the panel's Variables)")

    isolate_db(env, env_file)
    prepare(env)
    pg_proc = None
    if not (env.get("DATABASE_URL") or env_file.get("DATABASE_URL")):
        log("DATABASE_URL empty -> starting built-in local PostgreSQL (data in ./pgdata)")
        pg_proc, local_url = start_embedded_db(env)
        if local_url:
            env["DATABASE_URL"] = local_url
    app = subprocess.Popen(["node", "node_modules/next/dist/bin/next", "start", "-H", HOST, "-p", str(PORT)],
                           cwd=APP_DIR, env={**env, "NODE_ENV": "production"})
    # Export .env keys needed by tunnel.sh / child processes
    for k in ("CLOUDFLARE_TUNNEL_TOKEN", "APP_URL", "DATABASE_URL", "TELEGRAM_BOT_TOKEN",
              "TELEGRAM_WEBHOOK_SECRET", "SESSION_SECRET", "CRON_SECRET", "PROVIDER_ENCRYPTION_KEY"):
        v = env.get(k) or env_file.get(k)
        if v:
            env[k] = v
            os.environ[k] = v
    try:
        tunnel = start_tunnel()
    except Exception as e:
        log("!! tunnel failed, continuing without it:", e)
        tunnel = subprocess.Popen(["sleep", "infinity"])
    has_db = db_setup(env, env_file)      # after app+tunnel are up, so a DB problem can never block the site
    stop_evt = threading.Event()
    if has_db:
        threading.Thread(target=worker_loop, args=(env_file, stop_evt), daemon=True).start()
    log(f"app -> http://{HOST}:{PORT} | tunnel={'on' if tunnel else 'off'} | worker every 60s")

    def stop(*_):
        stop_evt.set()
        for p in (tunnel, app, pg_proc):
            if p is not None and p.poll() is None:
                p.terminate()
        if pg_proc is not None:
            try: pg_proc.wait(timeout=15)
            except Exception: pass
        sys.exit(0)

    signal.signal(signal.SIGINT, stop)
    signal.signal(signal.SIGTERM, stop)

    while True:
        if app.poll() is not None:
            log("app stopped, shutting down")
            stop()
        if tunnel is not None:
            code = tunnel.poll()
            if code == 2:      # token not filled in: keep the app running, don't loop
                log("tunnel disabled (optional on Apsara). App keeps running.")
                tunnel = subprocess.Popen(["sleep", "infinity"])
            elif code is not None:
                log(f"tunnel exited ({code}), restarting in 5s")
                time.sleep(5)
                try:
                    tunnel = start_tunnel()
                except Exception as e:
                    log("!! tunnel restart failed:", e)
                    tunnel = subprocess.Popen(["sleep", "infinity"])
        time.sleep(2)


if __name__ == "__main__":
    main()
